<script setup lang="ts">
import { computed, reactive } from 'vue'
import type { Aircraft, Station, Task } from '@sky/sky'
import { statusLabels } from '@sky/sky'
import type { DiscoveryDetail } from '@sky/environment'
const props = defineProps<{ detail: DiscoveryDetail; stations: Station[]; aircraft: Aircraft[]; tasks: Task[]; disabled: boolean }>()
defineEmits<{ respond: [input: { startStationId: string; endStationId: string; reason: string }]; taskAction: [taskId: string, action: string, aircraftId: string, reason: string] }>()
const form = reactive({ startStationId: '', endStationId: '', reason: '安排事件上空应急侦察', aircraftId: '' })
const stations = computed(() => props.stations.filter(s => s.status === 'enabled'))
const available = computed(() => props.aircraft.filter(a => a.type !== 'evtol' && a.status === 'idle'))
const active = computed(() => props.detail.responses.some(r => ['created', 'assigned', 'executing'].includes(props.tasks.find(t => t.id === r.taskId)?.status ?? r.taskStatus)))
const canCreate = computed(() => ['confirmed', 'in_response'].includes(props.detail.status) && !active.value)
function status(id: string, fallback: string) { return props.tasks.find(t => t.id === id)?.status ?? fallback }
</script>
<template><section v-if="detail.status !== 'pending_review' && detail.status !== 'rejected'" class="card"><h2>3 · 应急侦察任务</h2><p>航线从出发站起飞 → 80m巡航经过事件点 → 到回收站降落；不在河面降落，不代表真实救援。高/中/低事件的调度优先级下限为3/2/1，不抢占执行中任务。</p><div v-if="canCreate" class="fields"><label>出发站<select v-model="form.startStationId" aria-label="应急侦察出发站" :disabled="disabled"><option value="">请选择</option><option v-for="s in stations" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label>回收站<select v-model="form.endStationId" aria-label="应急侦察回收站" :disabled="disabled"><option value="">请选择不同站点</option><option v-for="s in stations" :key="s.id" :value="s.id" :disabled="s.id === form.startStationId">{{ s.name }}</option></select></label><label>任务操作原因<input v-model="form.reason" aria-label="应急任务原因" maxlength="500" :disabled="disabled"></label><el-button type="primary" :disabled="disabled || !form.reason.trim() || !form.startStationId || !form.endStationId || form.startStationId === form.endStationId" @click="$emit('respond', { startStationId: form.startStationId, endStationId: form.endStationId, reason: form.reason })">创建应急侦察任务</el-button></div>
  <div class="links"><RouterLink to="/agent-command">进入AI集群调度 →</RouterLink><RouterLink to="/traffic">预测冲突 / 预约错峰起飞 →</RouterLink></div><label v-if="active" class="resource">手动分配资源<select v-model="form.aircraftId" aria-label="应急分配飞行器" :disabled="disabled"><option value="">选择空闲无人机</option><option v-for="a in available" :key="a.id" :value="a.id">{{ a.name }} · {{ a.battery }}%</option></select></label><label v-if="active" class="resource">任务操作原因<input v-model="form.reason" aria-label="应急任务原因" maxlength="500" :disabled="disabled"></label>
  <article v-for="r in detail.responses" :key="r.id" class="response"><strong>第 {{ r.attempt }} 次 · {{ statusLabels[status(r.taskId, r.taskStatus)] }} · 优先级 {{ r.priority }}</strong><p>{{ r.taskId }} · {{ r.aircraftId || '尚未分配' }}</p><div class="links"><RouterLink v-if="status(r.taskId, r.taskStatus) === 'created'" :to="{ path: '/agent-command', query: { taskId: r.taskId } }">为此任务生成AI方案 →</RouterLink><RouterLink :to="{ path: '/route-planning', query: { taskId: r.taskId } }">查看 / 调整绕行航线 →</RouterLink><el-button v-if="status(r.taskId, r.taskStatus) === 'created'" :disabled="disabled || !form.aircraftId || !form.reason.trim()" @click="$emit('taskAction', r.taskId, 'assign', form.aircraftId, form.reason)">分配侦察飞行器</el-button><el-button v-if="status(r.taskId, r.taskStatus) === 'assigned'" :disabled="disabled || !form.reason.trim()" @click="$emit('taskAction', r.taskId, 'start', '', form.reason)">执行应急侦察</el-button><el-button v-if="['created', 'assigned', 'executing'].includes(status(r.taskId, r.taskStatus))" type="warning" :disabled="disabled || !form.reason.trim()" @click="$emit('taskAction', r.taskId, 'cancel', '', form.reason)">取消本次侦察</el-button></div></article>
</section></template>
<style scoped>.card { padding:20px; border:1px solid #24465d; background:#0b2132; }.card h2 { font-size:17px; margin-top:0; }.card p { font-size:12px; color:#a1bed0; line-height:1.8; }.fields,.links { display:flex; gap:14px; align-items:end; flex-wrap:wrap; margin:14px 0; }.fields label,.resource { display:grid; gap:6px; font-size:12px; color:#acc7d8; }.fields input,.fields select,.resource input,.resource select { padding:9px; border:1px solid #31546b; background:#102a3d; color:#e1f1fa; width:250px; }.resource { margin-bottom:12px; }.response { padding:16px 0; border-top:1px solid #24465d; }.response strong { font-size:14px; }.links a { color:#76cfeb; font-size:13px; }</style>
